import{_ as e,o as t,c as r,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Wood-cutting Source Profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/26-wood-cutting-profile.md","filePath":"reference/26-wood-cutting-profile.md","lastUpdated":1788517140000}'),o={name:"reference/26-wood-cutting-profile.md"};function n(s,a,c,l,d,h){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="wood-cutting-source-profile" tabindex="-1">Wood-cutting Source Profile <a class="header-anchor" href="#wood-cutting-source-profile" aria-label="Permalink to &quot;Wood-cutting Source Profile&quot;">​</a></h1><h2 id="claim-and-authority" tabindex="-1">Claim and authority <a class="header-anchor" href="#claim-and-authority" aria-label="Permalink to &quot;Claim and authority&quot;">​</a></h2><p>The <code>wood_cutting</code> activity is linked to <code>muhurta.wood_cutting</code>. Its authority is B. V. Raman&#39;s <em>Muhurtha</em>, Chapter XIII, &quot;Felling Trees,&quot; printed page 58 (PDF page 62 in the registered edition). Raman is a modern secondary authority, not scripture.</p><p>The passage says trees should be cut while Chandra is in the last quarter so that the timber will be strong and durable. The profile represents that quarter as Krishna Ashtami through Amavasya and admits only those exact Tithis.</p><h2 id="chart-level-condition" tabindex="-1">Chart-level condition <a class="header-anchor" href="#chart-level-condition" aria-label="Permalink to &quot;Chart-level condition&quot;">​</a></h2><p>Raman additionally requires a dry rising Rasi, preferably aspected by a dry Graha. The finder does not carry an authority-backed dry-sign classification or evaluate the aspect, so this remains a visible manual check. Hard-coding an uncited sign list would create false precision.</p><h2 id="separate-panchaka-rule" tabindex="-1">Separate Panchaka rule <a class="header-anchor" href="#separate-panchaka-rule" aria-label="Permalink to &quot;Separate Panchaka rule&quot;">​</a></h2><p>The activity already rejects Panchaka Nakshatras. That rule has separate project provenance and does not inherit authority from the felling-trees paragraph. The claim scope states this explicitly so a single citation cannot silently validate two independent criteria.</p><p>Python and MCP publish the stable claim ID, exact Tithi list, and practitioner check.</p>',9)])])}const m=e(o,[["render",n]]);export{p as __pageData,m as default};
